export type Card = {
  monster: string;
};

const SPHINX = "sphinx";

const containsSphinx = (army: Card[]): boolean =>
  army.some((card) => card.monster === SPHINX);

export const scoreArmy = (army: Card[]): number => (containsSphinx(army) ? 2 : 0);

input.new_string:
const countOtherTypes = (army: Card[]): number =>
  new Set(
    army.filter((card) => card.monster !== SPHINX).map((card) => card.monster),
  ).size;

export const scoreArmy = (army: Card[]): number => {
  if (!containsSphinx(army)) return 0;
  return countOtherTypes(army) > 3 ? 3 : 2;
};

