export type Card = {
  monster: string;
};

const SPHINX = "sphinx";

const containsSphinx = (army: Card[]): boolean =>
  army.some((card) => card.monster === SPHINX);

const countNonSphinxTypes = (army: Card[]): number => {
  const types = new Set(army.map((card) => card.monster));
  types.delete(SPHINX);
  return types.size;
};

const NO_SPHINX_SCORE = 0;
const FREE_TYPES = 3;
const SCORE_WITHIN_FREE_TYPES = 2;
const BASE_SCORE_BEYOND_FREE_TYPES = 1;
const POINTS_PER_EXTRA_TYPE = 2;

export const scoreArmy = (army: Card[]): number => {
  if (!containsSphinx(army)) return NO_SPHINX_SCORE;

  const otherTypes = countNonSphinxTypes(army);
  if (otherTypes <= FREE_TYPES) return SCORE_WITHIN_FREE_TYPES;

  const extraTypes = otherTypes - FREE_TYPES;
  return BASE_SCORE_BEYOND_FREE_TYPES + POINTS_PER_EXTRA_TYPE * extraTypes;
};

