export const scoreArmy = (army: Card[]): number => {
  const sphinxes = army.filter((card) => typeOf(card) === SPHINX);
  if (sphinxes.length === 0) return NO_SPHINX_SCORE;

  // A Sphinx counts the types it sees among the *other* cards. Sphinx is
